prologue:
enum { WorldGridCells = AMOD_ROOM_COLUMNS * AMOD_ROOM_ROWS, WorldSavedGrids = 4 };
static int g_world_sel_room = -1;
static int g_world_sel_maze_x = -1;
static int g_world_sel_maze_y = -1;
static int g_world_sel_col = 0;
static int g_world_sel_row = 0;
static int g_world_sel_box = 0;
static int g_world_sel_entity = -1;
static int g_world_sel_spawn = 0;
static int g_world_sel_light = 0;
static int g_world_sel_tri = 0;
static int g_world_sel_static = 0;
static int g_world_sel_thing = 0;
static int g_world_last_box = -1;
static int g_world_last_light = -1;
static int g_world_last_tri = -1;
static int g_world_last_static = -1;
static AmodWorldEventInfo g_world_last_ev;
static char g_world_saved_grids[WorldSavedGrids][WorldGridCells];
static unsigned char g_world_saved_valid[WorldSavedGrids];

static MOD_UNUSED int world_room_idx(int roomIndex) {
    if (roomIndex >= 0) return roomIndex;
    if (API->world == 0) return -1;
    return API->world->GetCurrentRoom(SELF);
}

static MOD_UNUSED int world_sel_room_idx(void) {
    return world_room_idx(g_world_sel_room);
}

static MOD_UNUSED void world_cancel(AmodToken tok) {
    if (tok == 0 || API->world == 0) return;
    if (API->world->Cancel != 0) API->world->Cancel(SELF, tok);
    else if (API->world->RemoveEventHandler != 0) API->world->RemoveEventHandler(SELF, tok);
}

static MOD_UNUSED void __cdecl world_event_relay(const AmodWorldEventInfo* info, void* user) {
    if (info != 0) g_world_last_ev = *info;
    if (user != 0) ((AmodWorldEventHandler)user)(info, 0);
}

static MOD_UNUSED int world_event_int(int which) {
    switch (which) {
        case 0: return (int)g_world_last_ev.event;
        case 1: return g_world_last_ev.roomIndex;
        case 2: return g_world_last_ev.roomId;
        case 3: return g_world_last_ev.previousRoomIndex;
        case 4: return g_world_last_ev.mazeX;
        case 5: return g_world_last_ev.mazeY;
        default: return 0;
    }
}

static MOD_UNUSED void world_toggle_paused(void) {
    if (API->world == 0 || API->world->IsPaused == 0 || API->world->SetPaused == 0) return;
    API->world->SetPaused(SELF, API->world->IsPaused(SELF) != 0 ? 0 : 1);
}

static MOD_UNUSED int world_read_level(AmodWorldLevel* out) {
    if (API->world == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->world->GetLevel(SELF, out);
}

static MOD_UNUSED const char* world_level_text(int which) {
    AmodWorldLevel lv;
    const char* s = 0;
    if (world_read_level(&lv) == 0) return "";
    switch (which) {
        case 0: s = lv.script; break;
        case 1: s = lv.name; break;
        case 2: s = lv.nextLevel; break;
        case 3: s = lv.background; break;
        case 4: s = lv.music; break;
        case 5: s = lv.startTitle; break;
        case 6: s = lv.endTitle; break;
        case 7: s = lv.menuStat; break;
        case 8: s = lv.castle; break;
        default: break;
    }
    return s != 0 ? s : "";
}

static MOD_UNUSED int world_level_int(int which) {
    AmodWorldLevel lv;
    if (world_read_level(&lv) == 0) return 0;
    switch (which) {
        case 0: return lv.number;
        case 1: return lv.isBonus;
        case 2: return lv.bonusCount;
        case 3: return lv.isDemoLevel;
        case 4: return lv.useForDemo;
        case 5: return lv.roomCount;
        case 6: return lv.mazeRows;
        case 7: return lv.startMazeX;
        case 8: return lv.startMazeY;
        default: return 0;
    }
}

static MOD_UNUSED float world_level_float(int which) {
    AmodWorldLevel lv;
    if (world_read_level(&lv) == 0) return 0.0f;
    switch (which) {
        case 0: return lv.time;
        case 1: return lv.musicStart;
        case 2: return lv.bonusTime;
        case 3: return lv.startCellX;
        case 4: return lv.startCellY;
        default: return 0.0f;
    }
}

static MOD_UNUSED int world_stat_val(int pair, int isTotal) {
    AmodLevelStats st;
    if (API->world == 0 || API->world->GetLevelStats == 0) return 0;
    memset(&st, 0, sizeof st);
    st.structSize = sizeof st;
    if (API->world->GetLevelStats(SELF, &st) == 0) return 0;
    switch (pair) {
        case 0: return isTotal ? st.crystalsTotal : st.crystalsTaken;
        case 1: return isTotal ? st.bonusesTotal : st.bonusesTaken;
        case 2: return isTotal ? st.superTotal : st.superTaken;
        case 3: return isTotal ? st.monstersTotal : st.monstersKilled;
        case 4: return isTotal ? st.lightRoomsTotal : st.lightRoomsSeen;
        case 5: return isTotal ? st.darkRoomsTotal : st.darkRoomsSeen;
        case 6: return isTotal ? st.secretRoomsTotal : st.secretRoomsSeen;
        case 7: return isTotal ? st.eighthTotal : st.eighthTaken;
        default: return 0;
    }
}

static MOD_UNUSED void world_set_stat(int pair, int taken, int total) {
    AmodLevelStats st;
    if (API->world == 0 || API->world->GetLevelStats == 0 || API->world->SetLevelStats == 0) return;
    memset(&st, 0, sizeof st);
    st.structSize = sizeof st;
    if (API->world->GetLevelStats(SELF, &st) == 0) return;
    switch (pair) {
        case 0: if (taken >= 0) st.crystalsTaken = taken; if (total >= 0) st.crystalsTotal = total; break;
        case 1: if (taken >= 0) st.bonusesTaken = taken; if (total >= 0) st.bonusesTotal = total; break;
        case 2: if (taken >= 0) st.superTaken = taken; if (total >= 0) st.superTotal = total; break;
        case 3: if (taken >= 0) st.monstersKilled = taken; if (total >= 0) st.monstersTotal = total; break;
        case 4: if (taken >= 0) st.lightRoomsSeen = taken; if (total >= 0) st.lightRoomsTotal = total; break;
        case 5: if (taken >= 0) st.darkRoomsSeen = taken; if (total >= 0) st.darkRoomsTotal = total; break;
        case 6: if (taken >= 0) st.secretRoomsSeen = taken; if (total >= 0) st.secretRoomsTotal = total; break;
        case 7: if (taken >= 0) st.eighthTaken = taken; if (total >= 0) st.eighthTotal = total; break;
        default: return;
    }
    API->world->SetLevelStats(SELF, &st);
}

static MOD_UNUSED void world_add_stat(int pair, int deltaTaken) {
    int cur = world_stat_val(pair, 0) + deltaTaken;
    if (cur < 0) cur = 0;
    world_set_stat(pair, cur, -1);
}

static MOD_UNUSED void world_select_room(int roomIndex) {
    g_world_sel_room = roomIndex;
}

static MOD_UNUSED void world_select_room_by_id(int roomId) {
    g_world_sel_room = API->world != 0 ? API->world->FindRoomById(SELF, roomId) : -1;
}

static MOD_UNUSED int world_pick_room(int idx) {
    if (API->world == 0 || idx < 0 || idx >= API->world->GetRoomCount(SELF)) return 0;
    g_world_sel_room = idx;
    return 1;
}

static MOD_UNUSED int world_read_room(int roomIndex, AmodWorldRoom* out) {
    int r = world_room_idx(roomIndex);
    if (API->world == 0 || r < 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->world->GetRoom(SELF, r, out);
}

static MOD_UNUSED int world_room_int(int which) {
    AmodWorldRoom rm;
    if (world_read_room(g_world_sel_room, &rm) == 0) {
        return (which == 0 || which == 2 || which == 3) ? -1 : 0;
    }
    switch (which) {
        case 0: return rm.index;
        case 1: return rm.id;
        case 2: return rm.mazeX;
        case 3: return rm.mazeY;
        case 4: return rm.isLoaded;
        case 5: return rm.hasBackWall;
        case 6: return rm.collisionBoxCount;
        case 7: return rm.lightTriangleCount;
        default: return 0;
    }
}

static MOD_UNUSED const char* world_room_text(int which) {
    AmodWorldRoom rm;
    const char* s = 0;
    if (world_read_room(g_world_sel_room, &rm) == 0) return "";
    s = which == 0 ? rm.file : rm.music;
    return s != 0 ? s : "";
}

static MOD_UNUSED void world_select_maze_cell(int x, int y) {
    g_world_sel_maze_x = x;
    g_world_sel_maze_y = y;
}

static MOD_UNUSED int world_maze_cursor(int isY) {
    int x = -1, y = -1;
    if (API->world != 0) API->world->GetMazeCursor(SELF, &x, &y);
    return isY ? y : x;
}

static MOD_UNUSED int world_maze_row_width(int y) {
    int row = y >= 0 ? y : (g_world_sel_maze_y >= 0 ? g_world_sel_maze_y : world_maze_cursor(1));
    return (API->world != 0 && row >= 0) ? API->world->GetMazeRowWidth(SELF, row) : 0;
}

static MOD_UNUSED int world_maze_room_id(int x, int y) {
    int mx = x >= 0 ? x : (g_world_sel_maze_x >= 0 ? g_world_sel_maze_x : world_maze_cursor(0));
    int my = y >= 0 ? y : (g_world_sel_maze_y >= 0 ? g_world_sel_maze_y : world_maze_cursor(1));
    return (API->world != 0 && mx >= 0 && my >= 0) ? API->world->GetMazeRoomId(SELF, mx, my) : 0;
}

static MOD_UNUSED int world_maze_room_index(int x, int y) {
    int id = world_maze_room_id(x, y);
    return (API->world != 0 && id > 0) ? API->world->FindRoomById(SELF, id) : -1;
}

static MOD_UNUSED int world_room_tex(int which) {
    int r = world_sel_room_idx();
    if (API->world == 0) return 0;
    if (which == 0) return API->world->GetRoomLightmap != 0 ? (int)API->world->GetRoomLightmap(SELF, r) : 0;
    if (which == 1) return API->world->GetRoomWallTexture != 0 ? (int)API->world->GetRoomWallTexture(SELF, r) : 0;
    return API->world->GetRoomFloorTexture != 0 ? (int)API->world->GetRoomFloorTexture(SELF, r) : 0;
}

static MOD_UNUSED int world_room_saved_size(int roomIndex) {
    return (API->world != 0 && API->world->GetRoomSavedSize != 0) ? API->world->GetRoomSavedSize(SELF, world_room_idx(roomIndex)) : 0;
}

static MOD_UNUSED int world_col_at(float x) {
    return (int)floorf((x - AMOD_ROOM_ORIGIN_X) / AMOD_ROOM_CELL_SIZE);
}

static MOD_UNUSED int world_row_at(float y) {
    return (int)floorf((AMOD_ROOM_ORIGIN_Y - y) / AMOD_ROOM_CELL_SIZE);
}

static MOD_UNUSED float world_cell_x(int col) {
    int c = col >= 0 ? col : g_world_sel_col;
    return AMOD_ROOM_ORIGIN_X + (float)c * AMOD_ROOM_CELL_SIZE;
}

static MOD_UNUSED float world_cell_y(int row) {
    int r = row >= 0 ? row : g_world_sel_row;
    return AMOD_ROOM_ORIGIN_Y - (float)r * AMOD_ROOM_CELL_SIZE;
}

static MOD_UNUSED void world_select_cell(int col, int row) {
    if (col < 0) col = 0;
    if (col >= AMOD_ROOM_COLUMNS) col = AMOD_ROOM_COLUMNS - 1;
    if (row < 0) row = 0;
    if (row >= AMOD_ROOM_ROWS) row = AMOD_ROOM_ROWS - 1;
    g_world_sel_col = col;
    g_world_sel_row = row;
}

static MOD_UNUSED void world_select_cell_pos(float x, float y) {
    world_select_cell(world_col_at(x), world_row_at(y));
}

static MOD_UNUSED int world_sel_col(void) {
    return g_world_sel_col;
}

static MOD_UNUSED int world_sel_row(void) {
    return g_world_sel_row;
}

static MOD_UNUSED int world_cell_code(int roomIndex, int col, int row) {
    int r = world_room_idx(roomIndex);
    int c = col >= 0 ? col : g_world_sel_col;
    int rw = row >= 0 ? row : g_world_sel_row;
    if (API->world == 0 || r < 0) return 0;
    return (int)(unsigned char)API->world->GetRoomCell(SELF, r, c, rw);
}

static MOD_UNUSED const char* world_cell_text(void) {
    static char buf[2];
    int ch = world_cell_code(g_world_sel_room, -1, -1);
    buf[0] = ch > 0 ? (char)ch : ' ';
    buf[1] = 0;
    return buf;
}

static MOD_UNUSED void world_set_cell(int roomIndex, int col, int row, int code) {
    int r = world_room_idx(roomIndex);
    int c = col >= 0 ? col : g_world_sel_col;
    int rw = row >= 0 ? row : g_world_sel_row;
    if (API->world == 0 || API->world->SetRoomCell == 0 || code <= 0) return;
    API->world->SetRoomCell(SELF, r, c, rw, (char)code);
}

static MOD_UNUSED void world_fill_cells_rect(int roomIndex, int col, int row, int w, int h, int code) {
    char cells[WorldGridCells];
    int x, y;
    if (API->world == 0 || API->world->SetRoomCells == 0 || code <= 0 || w <= 0 || h <= 0) return;
    memset(cells, 0, sizeof cells);
    for (y = row; y < row + h; ++y) {
        if (y < 0 || y >= AMOD_ROOM_ROWS) continue;
        for (x = col; x < col + w; ++x) {
            if (x < 0 || x >= AMOD_ROOM_COLUMNS) continue;
            cells[y * AMOD_ROOM_COLUMNS + x] = (char)code;
        }
    }
    API->world->SetRoomCells(SELF, world_room_idx(roomIndex), cells, WorldGridCells);
}

static MOD_UNUSED void world_snapshot_cells(int roomIndex, int slot) {
    int r = world_room_idx(roomIndex);
    if (API->world == 0 || r < 0 || slot < 0 || slot >= WorldSavedGrids) return;
    if (API->world->GetRoomCells(SELF, r, g_world_saved_grids[slot], WorldGridCells) == WorldGridCells) {
        g_world_saved_valid[slot] = 1;
    }
}

static MOD_UNUSED void world_restore_cells(int roomIndex, int slot) {
    if (API->world == 0 || API->world->SetRoomCells == 0 || slot < 0 || slot >= WorldSavedGrids) return;
    if (g_world_saved_valid[slot] == 0) return;
    API->world->SetRoomCells(SELF, world_room_idx(roomIndex), g_world_saved_grids[slot], WorldGridCells);
}

static MOD_UNUSED int world_count_cells(int roomIndex, int code) {
    char cells[WorldGridCells];
    int r = world_room_idx(roomIndex);
    int i, n = 0;
    if (API->world == 0 || r < 0) return 0;
    if (API->world->GetRoomCells(SELF, r, cells, WorldGridCells) != WorldGridCells) return 0;
    for (i = 0; i < WorldGridCells; ++i) {
        if ((unsigned char)cells[i] == (unsigned char)code) ++n;
    }
    return n;
}

static MOD_UNUSED int world_cell_free_byte(int roomIndex, int col, int row, int which) {
    unsigned char rec[AMOD_CELL_BYTES];
    int r = world_room_idx(roomIndex);
    int c = col >= 0 ? col : g_world_sel_col;
    int rw = row >= 0 ? row : g_world_sel_row;
    if (API->world == 0 || API->world->GetRoomCellRecord == 0 || which < 0 || which >= AMOD_CELL_FREE_COUNT) return 0;
    memset(rec, 0, sizeof rec);
    if (API->world->GetRoomCellRecord(SELF, r, c, rw, rec, AMOD_CELL_BYTES) == 0) return 0;
    return (int)rec[AMOD_CELL_FREE_FIRST + which];
}

static MOD_UNUSED void world_set_cell_byte(int roomIndex, int col, int row, int which, int value) {
    unsigned char rec[AMOD_CELL_BYTES];
    int r = world_room_idx(roomIndex);
    int c = col >= 0 ? col : g_world_sel_col;
    int rw = row >= 0 ? row : g_world_sel_row;
    if (API->world == 0 || API->world->GetRoomCellRecord == 0 || API->world->SetRoomCellRecord == 0) return;
    if (which < 0 || which >= AMOD_CELL_FREE_COUNT) return;
    memset(rec, 0, sizeof rec);
    if (API->world->GetRoomCellRecord(SELF, r, c, rw, rec, AMOD_CELL_BYTES) == 0) return;
    rec[AMOD_CELL_FREE_FIRST + which] = (unsigned char)value;
    API->world->SetRoomCellRecord(SELF, r, c, rw, rec, AMOD_CELL_BYTES);
}

static MOD_UNUSED void world_clear_cell_bytes(int roomIndex, int col, int row) {
    unsigned char rec[AMOD_CELL_BYTES];
    int r = world_room_idx(roomIndex);
    int c = col >= 0 ? col : g_world_sel_col;
    int rw = row >= 0 ? row : g_world_sel_row;
    int i;
    if (API->world == 0 || API->world->GetRoomCellRecord == 0 || API->world->SetRoomCellRecord == 0) return;
    memset(rec, 0, sizeof rec);
    if (API->world->GetRoomCellRecord(SELF, r, c, rw, rec, AMOD_CELL_BYTES) == 0) return;
    for (i = 0; i < AMOD_CELL_FREE_COUNT; ++i) rec[AMOD_CELL_FREE_FIRST + i] = 0;
    API->world->SetRoomCellRecord(SELF, r, c, rw, rec, AMOD_CELL_BYTES);
}

static MOD_UNUSED void world_select_box(int boxIndex) {
    g_world_sel_box = boxIndex;
}

static MOD_UNUSED int world_pick_box(int roomIndex, int idx) {
    AmodWorldBox b;
    int r = world_room_idx(roomIndex);
    if (API->world == 0 || r < 0 || idx < 0) return 0;
    if (API->world->GetRoomCollisionBox(SELF, r, idx, &b) == 0) return 0;
    g_world_sel_room = roomIndex;
    g_world_sel_box = idx;
    return 1;
}

static MOD_UNUSED int world_point_in_box(int roomIndex, int boxIndex, float x, float y, float z) {
    AmodWorldBox b;
    int r = world_room_idx(roomIndex);
    int idx = boxIndex >= 0 ? boxIndex : g_world_sel_box;
    if (API->world == 0 || r < 0 || idx < 0) return 0;
    memset(&b, 0, sizeof b);
    if (API->world->GetRoomCollisionBox(SELF, r, idx, &b) == 0) return 0;
    return x >= b.min[0] && x <= b.max[0] && y >= b.min[1] && y <= b.max[1] && z >= b.min[2] && z <= b.max[2];
}

static MOD_UNUSED int world_box_kind(int roomIndex, int boxIndex) {
    AmodRoomBox b;
    int r = world_room_idx(roomIndex);
    int idx = boxIndex >= 0 ? boxIndex : g_world_sel_box;
    if (API->world == 0 || API->world->GetRoomBox == 0 || idx < 0) return -1;
    memset(&b, 0, sizeof b);
    b.structSize = sizeof b;
    if (API->world->GetRoomBox(SELF, r, idx, &b) == 0) return -1;
    return b.kind;
}

static MOD_UNUSED float world_box_num(int which) {
    AmodRoomBox b;
    int r = world_sel_room_idx();
    if (API->world == 0 || API->world->GetRoomBox == 0 || g_world_sel_box < 0) return 0.0f;
    memset(&b, 0, sizeof b);
    b.structSize = sizeof b;
    if (API->world->GetRoomBox(SELF, r, g_world_sel_box, &b) == 0) return 0.0f;
    if (which >= 0 && which < 3) return b.min[which];
    if (which >= 3 && which < 6) return b.max[which - 3];
    return 0.0f;
}

static MOD_UNUSED void world_set_box(int roomIndex, int boxIndex, int kind, float minX, float minY, float minZ, float maxX, float maxY, float maxZ) {
    AmodRoomBox b;
    int idx = boxIndex >= 0 ? boxIndex : g_world_sel_box;
    if (API->world == 0 || API->world->SetRoomBox == 0 || idx < 0) return;
    memset(&b, 0, sizeof b);
    b.structSize = sizeof b;
    b.kind = kind;
    b.min[0] = minX; b.min[1] = minY; b.min[2] = minZ;
    b.max[0] = maxX; b.max[1] = maxY; b.max[2] = maxZ;
    API->world->SetRoomBox(SELF, world_room_idx(roomIndex), idx, &b);
}

static MOD_UNUSED void world_add_box(int roomIndex, int kind, float minX, float minY, float minZ, float maxX, float maxY, float maxZ) {
    AmodRoomBox b;
    int idx;
    if (API->world == 0 || API->world->AddRoomBox == 0) return;
    memset(&b, 0, sizeof b);
    b.structSize = sizeof b;
    b.kind = kind;
    b.min[0] = minX; b.min[1] = minY; b.min[2] = minZ;
    b.max[0] = maxX; b.max[1] = maxY; b.max[2] = maxZ;
    idx = API->world->AddRoomBox(SELF, world_room_idx(roomIndex), &b);
    if (idx >= 0) { g_world_last_box = idx; g_world_sel_box = idx; }
}

static MOD_UNUSED void world_remove_box(int roomIndex, int boxIndex) {
    int idx = boxIndex >= 0 ? boxIndex : g_world_last_box;
    if (API->world == 0 || API->world->RemoveRoomBox == 0 || idx < 0) return;
    if (API->world->RemoveRoomBox(SELF, world_room_idx(roomIndex), idx) != 0) {
        if (g_world_last_box == idx) g_world_last_box = -1;
    }
}

static MOD_UNUSED int world_last_box(void) {
    return g_world_last_box;
}

static MOD_UNUSED int world_entity_count(int roomIndex) {
    int r = world_room_idx(roomIndex);
    return (API->world != 0 && r >= 0) ? API->world->GetEntityCount(SELF, r) : 0;
}

static MOD_UNUSED void world_select_entity(int index) {
    g_world_sel_entity = index;
}

static MOD_UNUSED void world_select_player_entity(void) {
    g_world_sel_entity = (API->world != 0 && API->world->GetPlayerEntity != 0) ? API->world->GetPlayerEntity(SELF) : -1;
}

static MOD_UNUSED int world_player_entity(void) {
    return (API->world != 0 && API->world->GetPlayerEntity != 0) ? API->world->GetPlayerEntity(SELF) : -1;
}

static MOD_UNUSED int world_entity_idx(int index) {
    if (index >= 0) return index;
    if (g_world_sel_entity >= 0) return g_world_sel_entity;
    return world_player_entity();
}

static MOD_UNUSED int world_pick_entity(int roomIndex, int idx) {
    if (idx < 0 || idx >= world_entity_count(roomIndex)) return 0;
    g_world_sel_room = roomIndex;
    g_world_sel_entity = idx;
    return 1;
}

static MOD_UNUSED int world_read_entity(int roomIndex, int index, AmodWorldEntity* out) {
    int r = world_room_idx(roomIndex);
    int idx = world_entity_idx(index);
    if (API->world == 0 || r < 0 || idx < 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->world->GetEntity(SELF, r, idx, out);
}

static MOD_UNUSED int world_entity_int(int which) {
    AmodWorldEntity e;
    if (world_read_entity(g_world_sel_room, -1, &e) == 0) return 0;
    switch (which) {
        case 0: return e.kind;
        case 1: return e.state;
        case 2: return e.subState;
        case 3: return (int)e.flags;
        case 4: return e.isDead;
        case 5: return e.isLive;
        default: return 0;
    }
}

static MOD_UNUSED float world_entity_num(int which) {
    AmodWorldEntity e;
    if (world_read_entity(g_world_sel_room, -1, &e) == 0) return 0.0f;
    if (which >= 0 && which < 3) return e.position[which];
    if (which >= 3 && which < 6) return e.previousPosition[which - 3];
    return 0.0f;
}

static MOD_UNUSED const char* world_entity_name(void) {
    AmodWorldEntity e;
    if (world_read_entity(g_world_sel_room, -1, &e) == 0) return "";
