static MOD_UNUSED void world_add_static(int roomIndex, uint32_t model, uint32_t texture, float x, float y, float z, float scale, int isLit, int isTranslucent, int blend) {
    AmodRoomStatic s, proto;
    int r = world_room_idx(roomIndex);
    int idx;
    float sc = scale > 0.0f ? scale : 1.0f;
    if (API->world == 0 || API->world->AddStatic == 0) return;
    memset(&s, 0, sizeof s);
    s.structSize = sizeof s;
    if (model == 0 && world_read_static(r, 0, &proto) != 0) {
        model = proto.model;
        if (texture == 0) texture = proto.texture;
    }
    if (model == 0) return;
    s.isShown = 1;
    s.isLit = isLit != 0 ? 1 : 0;
    s.isTranslucent = isTranslucent != 0 ? 1 : 0;
    s.blend = blend;
    s.model = (AmodModelId)model;
    s.texture = (AmodTextureId)texture;
    s.matrix[0] = sc;
    s.matrix[5] = sc;
    s.matrix[10] = sc;
    s.matrix[12] = x;
    s.matrix[13] = y;
    s.matrix[14] = z;
    s.matrix[15] = 1.0f;
    idx = API->world->AddStatic(SELF, r, &s);
    if (idx >= 0) { g_world_last_static = idx; g_world_sel_static = idx; }
}

